xml.Script:
        clYellow   := 'FFFF00';
        clOrange   := 'FF6000';
        clCyan     := '00FFFF';
        clLime     := '00FF00';
        clBlue     := '0000FF';
        clPink     := 'FF69B4';
        clRed      := 'FF0000';
        clPurple   := '800080';
                   
        clGreen    := '008000';
        clKhaki    := 'F0E68C';
        clSeaGreen := '3cb371';
        clFuchsia  := 'FF00FF';

        clOrchid   := 'DA70D6';
        clCoral    := 'FF7F50';
        clNavy     := '000080';
        clDeepSky  := '00BFFF';

        K  := 0.6;
        H  := K * sqrt(2 * sqrt(2)) / 4;
        C1 := K * sqrt(2) / 2;
        C2 := K * 0.5;
        C3 := C1 + H;

        HD := H - K * 0.15; // variable
        D  := HD * C3 / sqrt(2 * C2^2 + HD^2);

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        A1 := Angle( C2, C2, HD,  C1,  0,-HD,   0, C1,-HD);
        A2 := Angle( C2, C2, HD,  C2,-C2, HD, -C2, C2, HD);
